/* Token Radar — dark-warm dusk theme. Static, offline, no external assets. */

:root {
  --bg: #171009;
  --bg-soft: #201709;
  --panel: #241a10;
  --panel-2: #2c2113;
  --line: #3d2c17;
  --line-soft: #2e2214;
  --text: #f2e7d5;
  --muted: #b8a684;
  --faint: #8a7a5f;
  --accent: #f0a832;
  --accent-soft: #7a5a22;
  --farm: #7bc47f;
  --farm-bg: #1e3320;
  --thin: #f0a832;
  --thin-bg: #3a2a10;
  --skip: #8a7f70;
  --skip-bg: #2a2622;
  --high: #7bc47f;
  --medium: #f0c35c;
  --low: #c97b5a;
  --danger: #e07840;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "Avenir Next", "Segoe UI", system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.5;
}

.top {
  display: flex;
  flex-wrap: wrap;
  gap: 16px 32px;
  align-items: flex-end;
  justify-content: space-between;
  padding: 28px 32px 18px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, #2b1d0c 0%, var(--bg) 100%);
}

.brand { display: flex; gap: 14px; align-items: center; }

.pulse {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 0 rgba(240, 168, 50, 0.6);
  animation: pulse 2.4s infinite;
}

@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(240, 168, 50, 0.55); }
  70% { box-shadow: 0 0 0 12px rgba(240, 168, 50, 0); }
  100% { box-shadow: 0 0 0 0 rgba(240, 168, 50, 0); }
}

h1 {
  margin: 0;
  font-size: 30px;
  letter-spacing: 0.04em;
  line-height: 1.1;
}

.tagline { margin: 4px 0 0; color: var(--muted); font-size: 14px; }

.stats { display: flex; gap: 10px; flex-wrap: wrap; }

.stat {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 8px 14px;
  min-width: 96px;
}

.stat b { display: block; font-size: 20px; color: var(--accent); line-height: 1.2; }
.stat span { font-size: 12px; color: var(--muted); }

main { padding: 20px 32px 8px; max-width: 1240px; margin: 0 auto; }

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  margin-bottom: 14px;
}

.controls input[type="search"],
.controls select {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 14px;
  outline: none;
}

.controls input[type="search"] { flex: 1 1 220px; min-width: 180px; }
.controls input[type="search"]:focus,
.controls select:focus { border-color: var(--accent); }

.chips { display: flex; gap: 6px; }

.chip {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px 14px;
  font-size: 13px;
  cursor: pointer;
}

.chip.active { background: var(--accent); color: #241a10; border-color: var(--accent); font-weight: 700; }
.chip.farm.active { background: var(--farm); color: #12230f; border-color: var(--farm); }
.chip.thin.active { background: var(--thin); color: #241a10; border-color: var(--thin); }
.chip.skip.active { background: var(--skip); color: #1d1a16; border-color: var(--skip); }

.count { color: var(--muted); font-size: 13px; margin: 4px 0 10px; }

.board { width: 100%; border-collapse: collapse; background: var(--panel); border: 1px solid var(--line); border-radius: 10px; overflow: hidden; }

.board th,
.board td { padding: 9px 12px; text-align: left; border-bottom: 1px solid var(--line-soft); }

.board th {
  color: var(--muted);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  background: var(--panel-2);
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
}

.board th.sorted { color: var(--accent); }
.board th.sorted::after { content: " ▲"; font-size: 10px; }
.board th.sorted.sort-desc::after { content: " ▼"; }
.board th.num, .board td.num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.board td.name { font-weight: 600; white-space: nowrap; }
.board td.name small { display: block; font-weight: 400; color: var(--faint); font-size: 12px; }
.board tbody tr { cursor: pointer; }
.board tbody tr:hover { background: var(--panel-2); }
.board tbody tr.selected { background: #33240f; }
.board tbody tr:last-child td { border-bottom: none; }

.pos { color: #7ec97b; }
.neg { color: #e07840; }

.tag {
  display: inline-block;
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 12px;
  font-weight: 700;
}

.tag.farm { background: var(--farm-bg); color: var(--farm); }
.tag.thin { background: var(--thin-bg); color: var(--thin); }
.tag.skip { background: var(--skip-bg); color: var(--skip); }
.tag.high { background: var(--farm-bg); color: var(--high); }
.tag.medium { background: var(--thin-bg); color: var(--medium); }
.tag.low { background: #332016; color: var(--low); }
.tag.watch { background: #2c2a4a; color: #b9b3ff; }

.chain-chip {
  display: inline-block;
  background: var(--bg-soft);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 1px 7px;
  margin: 1px 2px 1px 0;
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
}

.detail {
  background: var(--panel);
  border: 1px solid var(--accent-soft);
  border-radius: 12px;
  padding: 20px 22px;
  margin-bottom: 16px;
}

.detail h2 { margin: 0 0 4px; font-size: 24px; }
.detail .sub { color: var(--muted); margin: 0 0 14px; }
.detail h3 { margin: 18px 0 8px; font-size: 14px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--accent); }

.detail .facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
  margin: 0 0 6px;
}

.fact { background: var(--bg-soft); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }
.fact b { display: block; font-size: 17px; font-variant-numeric: tabular-nums; }
.fact span { font-size: 12px; color: var(--muted); }
.fact small { display: block; color: var(--faint); font-size: 11px; }

.detail ul, .detail ol { margin: 0; padding-left: 20px; }
.detail li { margin-bottom: 5px; }
.detail li::marker { color: var(--accent); }

.detail .close {
  float: right;
  background: none;
  border: 1px solid var(--line);
  color: var(--muted);
  border-radius: 8px;
  padding: 4px 10px;
  cursor: pointer;
  font-size: 13px;
}

.empty { color: var(--muted); text-align: center; padding: 32px 0; }

footer {
  max-width: 1240px;
  margin: 0 auto;
  padding: 18px 32px 32px;
  color: var(--faint);
  font-size: 13px;
}

@media (max-width: 760px) {
  .top, main, footer { padding-left: 14px; padding-right: 14px; }
  .board th:nth-child(4), .board td:nth-child(4) { display: none; }
}
